import {closeSync, existsSync, openSync, readFileSync, renameSync, unlinkSync, writeFileSync} from 'node:fs';

/**
 * Reserve before submitting. Playwright restarts workers after failures, so a
 * process-global counter would reuse already-consumed MFA recovery credentials.
 * Only non-secret counters are persisted in the disposable fixture directory.
 * The exclusive lock also fails closed if a future runner enables parallel use.
 */
export function reserveRecoverySlot(file: string, role: string, available: number): number {
  const lock = file + '.lock';
  const fd = openSync(lock, 'wx', 0o600);
  try {
    const counters: Record<string, number> = existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : {};
    const index = Object.hasOwn(counters, role) ? counters[role] : 0;
    if (!Number.isSafeInteger(index) || index < 0 || index >= available) {
      throw new Error('Synthetic recovery proofs exhausted; provision a fresh isolated fixture.');
    }
    Object.defineProperty(counters, role, {value: index + 1, writable: true, enumerable: true, configurable: true});
    writeFileSync(file + '.tmp', JSON.stringify(counters), {mode: 0o600});
    renameSync(file + '.tmp', file);
    return index;
  } finally {
    closeSync(fd);
    unlinkSync(lock);
  }
}

/** Neutral names never disclose the original customer filename or identity. */
export function evidenceFilename(mime: string): string {
  const extensions: Record<string, string> = {
    'image/png': 'png',
    'image/jpeg': 'jpg',
    'application/pdf': 'pdf',
  };
  const type = mime.split(';', 1)[0].trim().toLowerCase();
  if (!Object.hasOwn(extensions, type)) throw new Error('Unsupported private evidence type. Do not open this response.');
  return `private-evidence.${extensions[type]}`;
}

import {describe, expect, it} from 'vitest';
import {mkdtempSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {evidenceFilename} from '../src/evidence';
import {reserveRecoverySlot} from '../e2e/recovery-slots';

describe('neutral private evidence filenames', () => {
  for (const [mime, name] of [['image/png', 'private-evidence.png'], ['image/jpeg', 'private-evidence.jpg'], ['application/pdf', 'private-evidence.pdf'], ['IMAGE/PNG; charset=binary', 'private-evidence.png']]) {
    it(mime, () => expect(evidenceFilename(mime)).toBe(name));
  }
  for (const mime of ['text/html', 'image/svg+xml', 'application/javascript', '', '__proto__']) {
    it('rejects ' + mime, () => expect(() => evidenceFilename(mime)).toThrow());
  }
});
it('reserves distinct proofs across simulated worker restarts without persisting secrets', () => {
  const dir = mkdtempSync(join(tmpdir(), 'admin-proof-test-'));
  const file = join(dir, 'usage.json');
  try {
    expect(reserveRecoverySlot(file, 'admin', 2)).toBe(0);
    expect(JSON.parse(readFileSync(file, 'utf8'))).toEqual({admin: 1});
    expect(reserveRecoverySlot(file, 'admin', 2)).toBe(1);
    expect(() => reserveRecoverySlot(file, 'admin', 2)).toThrow(/exhausted/);
    expect(reserveRecoverySlot(file, 'support', 2)).toBe(0);
    writeFileSync(file + '.lock', '');
    expect(() => reserveRecoverySlot(file, 'support', 2)).toThrow();
  } finally { rmSync(dir, {recursive: true, force: true}); }
});
